  const STAGES = [['meine', 'Meine Vorlagen'], ['gs', 'Grundschule und Förderschule'], ['sek', 'Mittelschule, Realschule, Gymnasium'], ['alle', 'Für alle Schularten']];
  function build(t) {
    const kind = t.opt.kind || 'arbeitsblatt'; const stage = t.stage === 'sek' ? 'sek' : 'primar';
    const d = newDocWithLayout(kind, stage); d.title = t.opt.title || t.titel; d.subject = t.fach === 'Alle Fächer' ? '' : t.fach; d.grades = t.jg.slice(); d.topic = t.bereich; d.tags = 'Vorlage';
    if (t.opt.assess) { d.assess = t.opt.assess; d.settings.headStyle = 'leistung'; }
    if (t.opt.draft) d.tags += ', Entwurf';
    if (t.opt.noFill) d.noFiller = true;
    if (t.opt.filler) d.fillerOpt = t.opt.filler;
    d.items = t.items.filter(Boolean).map(([type, props]) => {
      const it = makeItem(type); Object.assign(it, JSON.parse(JSON.stringify(props)));
      if (!props.source && ['text', 'pairs', 'words', 'options', 'items', 'events', 'btext'].some(k => k in props) && T0(type) && T0(type).props.some(p => p.k === 'source')) it.source = 'eigene';
      G.fill(it); regen(it);
      if (d.kind === 'probe' && RD.TASK.has(type) && !('points' in props) && typeof suggestPoints === 'function') { const p = suggestPoints(it, d); if (p != null) { it.points = p; it.pointsAuto = true; } }
      return it;
    });
    return d;
  }
  const T0 = type => C.TYPES[type];
  /* Vorlage an die Seite anpassen: Anzahlen so erhöhen, dass das Blatt gut gefüllt ist (ohne neue Seite);
     eine fast leere letzte Seite wird nach Möglichkeit eingespart. Nur eigene Kopien werden verändert. */
  const NOGROW = new Set(['wordsearch', 'crossword', 'secret', 'selfcheck', 'mindmap', 'chart', 'label', 'timeline', 'geoboard']);
  function amountOf(it, shrink) {
    const t = T0(it.type); if (!t || (!shrink && NOGROW.has(it.type)) || it.source === 'eigene' && !t.gen) return null;
    for (const k of ['count', 'n', 'rows']) { const p = t.props.find(q => q.k === k && q.type === 'number' && (!q.when || q.when(it))); if (p && it[k] != null && it[k] !== '') return { k, min: Math.max(1, p.min || 1), max: Math.min(p.max || 20, k === 'rows' ? 12 : 40) }; }
    return null;
  }
  function setAmount(it, k, v) { it[k] = v; if (G.FILL[it.type] && it.source && it.source !== 'eigene') G.fill(it); regen(it); }
  async function measure(d) { const pages = await paginate(d); const max = RD.dims(d).ch * 3.7795275591; const last = pages[pages.length - 1]; const h = last.reduce((s, b) => s + (b.free ? 0 : (b.h || 0)), 0); return { n: pages.length, fill: h / max, tall: pages.flat().some(b => b.tall || b.zoom), err: d.items.some(it => it.data && it.data.error) }; }
  async function fitDoc(d, target = .86) {
    if (d.kind === 'probe') { delete d.noFiller; delete d.fillerOpt; return d; } /* Leistungsnachweise: Anzahlen und Punkte bleiben wie festgelegt */
    const cand = d.items.map(it => ({ it, a: amountOf(it) })).filter(x => x.a);
    let m = await measure(d);
    /* 1. fast leere letzte Seite einsparen */
    const sc = d.items.map(it => ({ it, a: amountOf(it, true) })).filter(x => x.a);
    if (m.n > 1 && m.fill < .3 && sc.length) {
      const backup = sc.map(c => c.it[c.a.k]); let ok = false;
      for (let step = 0; step < 40 && !ok; step++) { const c = sc[step % sc.length]; const v = +c.it[c.a.k]; if (v - 1 < Math.max(c.a.min, 2)) continue; setAmount(c.it, c.a.k, v - 1); const m2 = await measure(d); if (m2.n < m.n && !m2.err) { ok = true; m = m2; } }
      if (!ok) { sc.forEach((c, i) => { if (c.it[c.a.k] !== backup[i]) setAmount(c.it, c.a.k, backup[i]); }); m = await measure(d); }
    }
    /* 2. auffüllen, solange keine neue Seite entsteht */
    const pagesGoal = m.n; const stale = new Map(); const done = new Set();
    for (let step = 0; step < 60 && m.fill < target && done.size < cand.length; step++) {
      const c = cand[step % cand.length]; if (done.has(c)) continue;
      const v = +c.it[c.a.k]; if (v + 1 > c.a.max) { done.add(c); continue; }
      setAmount(c.it, c.a.k, v + 1); const m2 = await measure(d);
      if (m2.n > pagesGoal || m2.tall || m2.err) { setAmount(c.it, c.a.k, v); done.add(c); continue; }
      if (Math.abs(m2.fill - m.fill) < .004) { const s2 = (stale.get(c) || 0) + 1; stale.set(c, s2); if (s2 >= 4) done.add(c); } else stale.set(c, 0);
      m = m2;
    }
    /* 3. bleibt viel Platz, passend zum Fach ergänzen (nicht bei Leistungsnachweisen) */
    if (d.kind !== 'probe' && m.fill < .72 && !d.noFiller) {
      const rem = (1 - m.fill) * RD.dims(d).ch - 16;
      if (rem >= 32) { const f = fillerFor(d, rem); if (f) { const it = makeItem(f[0]); Object.assign(it, f[1]); regen(it); d.items.push(it); const m2 = await measure(d); if (m2.n > m.n || m2.tall) { d.items.pop(); } } }
    }
    delete d.noFiller; delete d.fillerOpt;
    return d;
  }
  function fillerFor(d, rem) {
    const s = d.stage || (d.settings && d.settings.fontC === 'grundschrift' ? 'primar' : 'sek'); const gs = (d.grades || []).length ? Math.max(...d.grades) <= 4 : s === 'primar';
    const lines = (title, sp) => ['lines', { title, count: Math.max(2, Math.floor((rem - 4) / sp)), spacing: sp }];
    const space = (title, style) => ['space', { title, style, height: Math.max(25, Math.floor(rem - 6)) }];
    const f = d.subject || '';
    if (d.fillerOpt) { const [title, style] = d.fillerOpt; return style === 'lines' ? lines(title, 10) : space(title, style); }
    if (gs) {
      if (f === 'Mathematik') return space('Erfinde eigene Aufgaben und rechne sie.', 'karo');
      if (f === 'Deutsch') return lines('Schreibe eigene Sätze mit Wörtern von diesem Blatt.', 10);
      if (f === 'Englisch') return space('Draw and write: Male und schreibe auf Englisch.', 'rahmen');
      return space('Male ein Bild zum Thema.', 'rahmen');
    }
    if (f === 'Mathematik') return space('Platz für Nebenrechnungen', 'karo');
    const L = { Englisch: 'Write sentences with words from this sheet.', Italienisch: 'Scrivi delle frasi con le parole di questa scheda.', Französisch: 'Écris des phrases avec les mots de cette fiche.', Spanisch: 'Escribe frases con las palabras de esta hoja.' };
    if (L[f]) return lines(L[f], 8);
    return lines('Fasse das Wichtigste in eigenen Worten zusammen.', 8);
  }
  function open() {
    let stage = stageDefault() === 'sek' ? 'sek' : 'gs', fach = '', q = '';
    dialog({ title: 'Vorlagen', wide: true, html: `<div class="bildTop"><div class="search">${ICO.search}<input type="search" id="vq" placeholder="Vorlagen durchsuchen, z. B. Einmaleins, Brüche, Feuerwehr …"></div></div><div class="vlWrap"><nav class="vlNav" id="vNav"></nav><div class="vlList" id="vList"></div></div>
      <p class="hint" style="margin:8px 0 0">Jede Vorlage wird als eigene Kopie angelegt – mit frisch erzeugten Aufgaben. Alles lässt sich danach anpassen. Die Einteilung orientiert sich am LehrplanPLUS; Inhalte sind eigenständig erstellt.</p>`,
      onOpen: (dl, close) => {
        const nav = dl.querySelector('#vNav'), list = dl.querySelector('#vList');
        const drawNav = () => {
          let h = '';
          const mine = [...docs.values()].filter(d => d.tpl && !d.deleted);
          h += `<div class="vlS">Meine Vorlagen</div><button data-s="meine" data-f="" class="${stage === 'meine' ? 'on' : ''}">Selbst gespeichert <span class="hint">(${mine.length})</span></button>`;
          STAGES.filter(([s]) => s !== 'meine').forEach(([s, n]) => { const subs = [...new Set(V.filter(x => x.stage === s).map(x => x.fach))]; h += `<div class="vlS">${esc(n)}</div>` + subs.map(f => `<button data-s="${s}" data-f="${esc(f)}" class="${s === stage && f === fach ? 'on' : ''}">${esc(f)} <span class="hint">(${V.filter(x => x.stage === s && x.fach === f).length})</span></button>`).join(''); });
          nav.innerHTML = h;
          nav.querySelectorAll('[data-s]').forEach(b => b.onclick = () => { stage = b.dataset.s; fach = b.dataset.f; dl.querySelector('#vq').value = ''; q = ''; drawNav(); draw(); });
        };
        const draw = () => {
          const term = q.trim().toLowerCase();
          if (stage === 'meine' && !term) {
            const mine = [...docs.values()].filter(d => d.tpl && !d.deleted).sort((a, b) => a.title.localeCompare(b.title, 'de'));
            list.innerHTML = mine.length ? `<div class="vlGrp"><h3>Meine Vorlagen</h3><div class="vlCards">${mine.map(d => `<button class="vlCard" data-mine="${d.id}"><b>${esc(d.title)}</b><small>${esc([d.subject, d.grades.length ? 'Jg. ' + d.grades.join('/') : '', d.topic].filter(Boolean).join(' · ') || 'eigene Vorlage')}</small></button>`).join('')}</div></div>` : '<p class="hint">Noch keine eigenen Vorlagen. Öffne ein Material und wähle rechts „Als eigene Vorlage speichern …“.</p>';
            list.querySelectorAll('[data-mine]').forEach(b => b.onclick = async () => { const c = useTemplate(docs.get(b.dataset.mine)); close(); docs.set(c.id, c); markDirty(c); await flush(); openDoc(c); toast('Aus deiner Vorlage angelegt.'); });
            return;
          }
          let items = V.map((x, i) => ({ ...x, i })).filter(x => term ? term.split(/\s+/).every(w => (x.titel + ' ' + x.desc + ' ' + x.bereich + ' ' + x.fach + ' ' + x.jg.join(' ')).toLowerCase().includes(w)) : x.stage === stage && (!fach || x.fach === fach));
          const groups = new Map(); items.forEach(x => { const k = term ? x.fach : (x.jg.length ? 'Jahrgangsstufe ' + x.jg.join('/') : x.bereich); if (!groups.has(k)) groups.set(k, []); groups.get(k).push(x); });
          list.innerHTML = items.length ? [...groups.entries()].map(([k, arr]) => `<div class="vlGrp"><h3>${esc(k)}</h3><div class="vlCards">${arr.map(x => `<button class="vlCard" data-i="${x.i}">${x.opt.draft ? '<span class="vlTag">Entwurf · Quellen angegeben</span>' : x.opt.kind === 'probe' ? `<span class="vlTag" style="color:var(--accent)">${esc(x.opt.assess || 'Probe')}</span>` : ''}<b>${esc(x.titel)}</b><small>${esc(x.fach)} · ${esc(x.bereich)}${x.desc ? ' · ' + esc(x.desc) : ''}</small></button>`).join('')}</div></div>`).join('') : '<p class="hint">Keine Vorlage gefunden.</p>';
          list.querySelectorAll('[data-i]').forEach(b => b.onclick = async () => { if (open.busy) return; open.busy = true; list.querySelectorAll('[data-i]').forEach(x => x.disabled = true); b.classList.add('busy'); let d; try { d = build(V[+b.dataset.i]); await fitDoc(d); } finally { open.busy = false; } close(); docs.set(d.id, d); markDirty(d); await flush(); openDoc(d); toast('Vorlage als eigenes Material angelegt.'); });
        };
        dl.querySelector('#vq').oninput = e => { q = e.target.value; draw(); };
        if (!fach) fach = (V.find(x => x.stage === stage) || {}).fach || '';
        drawNav(); draw();
      } });
  }
  return { open, build, fitDoc, V };
